// 1. Obtener UsuarioID desde el entorno
var rawUsuarioId = pm.environment.get("UsuarioID");
var usuarioIdNum = parseInt(rawUsuarioId, 10);

if (isNaN(usuarioIdNum)) {
    console.warn("UsuarioID no está configurado en el entorno o es inválido. Usando valor por defecto: 1");
    usuarioIdNum = 1;
}

// 2. Construir la consulta SQL: factura de Tigo pendiente/vencida con vencimiento hoy
const queryBody = {
    sql: "SELECT id FROM facturas WHERE proveedor = $1 AND estado IN ($2, $3) AND fecha_vencimiento = CURRENT_DATE AND usuario_id = $4 LIMIT 1",
    params: ["Tigo", "pendiente", "vencida", usuarioIdNum]
};

// 3. Obtener baseUrl y apiKey
var baseUrl = pm.collectionVariables.get("baseUrl") || pm.environment.get("baseUrl");
var apiKey = pm.collectionVariables.get("apiKey") || pm.environment.get("apiKey");

// 4. Ejecutar la peticion SQL previa (con x-api-key)
pm.sendRequest({
    url: baseUrl + "/api/v1/sql/select",
    method: 'POST',
    header: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey
    },
    body: {
        mode: 'raw',
        raw: JSON.stringify(queryBody)
    }
}, function (err, res) {
    if (err) {
        console.error("Error al ejecutar Pre-request SQL:", err);
        pm.collectionVariables.set("ID_tabla", 0);
        return;
    }

    var responseData = res.json();

    if (responseData && responseData.data && responseData.data.length > 0) {
        var rawId = responseData.data[0].id;
        var idNumerico = parseInt(rawId, 10);

        if (!isNaN(idNumerico)) {
            pm.collectionVariables.set("ID_tabla", idNumerico);
            console.log("✓ ID_tabla asignado con éxito:", idNumerico);
        } else {
            console.error("El id retornado no es interpretable como numero:", rawId);
            pm.collectionVariables.set("ID_tabla", 0);
        }
    } else {
        console.warn("No se encontro una factura de Tigo con vencimiento hoy para el usuario:", usuarioIdNum);
        console.warn("Respuesta SQL:", JSON.stringify(responseData));
        pm.collectionVariables.set("ID_tabla", 0);
    }
});

// Helper local (autocontenido, no depende del nivel colección).
function bodySqlRest(sql, params) {
  return {
    url: pm.variables.get("baseUrl") + "/api/v1/sql/select",
    method: "POST",
    header: {
      "Content-Type": "application/json",
      "x-api-key": pm.variables.get("x-api-key")
    },
    body: { mode: "raw", raw: JSON.stringify({ sql: sql, params: params || [] }) }
  };
}

// Id de la factura que vamos a eliminar 
const ID = 6; // factura , activo: true
pm.variables.set("ID", ID);

// Verificamos en la BD que la factura existe y está activa ANTES de eliminarla.
const req = bodySqlRest(
  "SELECT id, activo, estado FROM qa_training.facturas WHERE id = $1",
  [ID]
);
pm.sendRequest(req, (err, res) => {
  if (err) { console.error("Pre-request SQL check falló:", err); return; }
  const rows = res.json().data || [];
  const factura = rows.find((r) => r.id === ID);
  console.log("Factura encontrada?", !!factura, "| activo:", factura && factura.activo);
});

function bodySqlRest(sql, params) {
  return {
    url: pm.variables.get("baseUrl") + "/api/v1/sql/select",
    method: "POST",
    header: {
      "Content-Type": "application/json",
      "x-api-key": pm.variables.get("apiKey")
    },
    body: { mode: "raw", raw: JSON.stringify({ sql: sql, params: params || [] }) }
  };
}

pm.test("Status 204 No Content", () => {
  pm.response.to.have.status(204);
});

pm.test("La respuesta no trae cuerpo", () => {
  pm.expect(pm.response.text()).to.eql("");
});

// Post-request: volvemos a consultar la BD para confirmar que activo pasó a false.
const facturaId = pm.variables.get("ID");
const req = bodySqlRest(
  "SELECT id, activo FROM qa_training.facturas WHERE id = $1",
  [facturaId]
);
pm.sendRequest(req, (err, res) => {
  pm.test("La BD confirma que la factura quedó con activo = false", () => {
    if (err) throw err;
    const row = res.json().data[0];
    pm.expect(row, "no se encontró la factura en la BD").to.not.be.undefined;
    pm.expect(row.activo).to.eql(false);
  });
});

